package com.bank.stmtbatch.model;

import jakarta.persistence.*;
import java.io.Serializable;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.Objects;

@Entity
@Table(name = "statements")
@IdClass(Statement.Key.class)
public class Statement {

    @Id @Column(name = "customer_id") private String customerId;
    @Id private String period;
    @Column(nullable = false, precision = 15, scale = 2) private BigDecimal amount;
    @Column(name = "created_at") private LocalDateTime createdAt;

    protected Statement() {}
    public Statement(String customerId, String period, BigDecimal amount) {
            this.customerId = customerId;
            this.period = period
            this.amount = amount;
        this.createdAt = LocalDateTime.now();
    }
    public String getCustomerId() { return customerId; }
    public String getPeriod() { return period; }

    public static class Key implements Serializable {
        private String customerId; private String period;
        public Key() {}
            public Key(String customerId, String period) { this.customerId = customerId;
            this.period = period; }
        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Key k)) return false;
            return Objects.equals(customerId, k.customerId) && Objects.equals(period, k.period);
        }
        @Override public int hashCode() { return Objects.hash(customerId, period); }
    }
}
