package com.bank.stmtbatch.service;

import com.bank.stmtbatch.model.Statement;
import com.bank.stmtbatch.repository.StatementRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class StatementService {

    private final StatementRepository statementRepo;

    // Idempotent: upsert by (customer, period) → a duplicate run produces no duplicate statement
    @Transactional
    public int generateForPeriod(String period) {
        List<String> customers = List.of("CUST-RAJESH", "CUST-PRIYA");
        int count = 0;
        for (String customerId : customers) {
            // save() with existing (customer, period) key merges → no duplicate row
            statementRepo.save(new Statement(customerId, period, new BigDecimal("1000000")));
            count++;
        }
        log.info("Generated {} statements for {} (idempotent upsert — safe even if run twice)", count, period);
        return count;
    }
}
