package com.bank.stmtbatch.job;

import com.bank.stmtbatch.service.StatementService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.javacrumbs.shedlock.spring.annotation.SchedulerLock;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import java.time.YearMonth;

@Component
@RequiredArgsConstructor
@Slf4j
public class StatementJob {

    private final StatementService statementService;

    // @SchedulerLock → only ONE instance across the cluster runs this per trigger.
    //   lockAtMostFor : auto-release if the holder crashes (safety)
    //   lockAtLeastFor: hold at least this long to prevent a fast second run (clock skew guard)
    @Scheduled(cron = "0 0 0 1 * *")   // midnight on the 1st of every month
    @SchedulerLock(name = "statementGeneration",
                   lockAtMostFor = "PT30M",
                   lockAtLeastFor = "PT5M")
    public void generateMonthlyStatements() {
        String period = YearMonth.now().minusMonths(1).toString();   // last month
        log.info("[instance holds lock] Generating statements for {}", period);
        statementService.generateForPeriod(period);
    }
}
