// Test harness: models N instances racing for ONE lock; exactly one should win.
package com.bank.stmtbatch.cluster;

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

public class SimulatedCluster {

    private final AtomicBoolean lockHeld = new AtomicBoolean(false);
    private final AtomicInteger ranCount = new AtomicInteger(0);

    // Mimics ShedLock: only the instance that atomically acquires the lock runs the job.
    public boolean tryRunOnInstance(String instanceId, Runnable job) {
        if (lockHeld.compareAndSet(false, true)) {   // atomic acquire (like the DB row lock)
                try { job.run(); ranCount.incrementAndGet();
                return true; }
            finally { /* in real ShedLock lock_until governs release; here we keep it held */ }
        }
        return false;   // lock already held → this instance skips
    }

    public int ranCount() { return ranCount.get(); }
}
