package com.bank.stmtbatch;

import com.bank.stmtbatch.cluster.SimulatedCluster;
import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.*;

class SingleExecutionTest {

    @Test
    void onlyOneInstanceRunsWhenAllRaceForTheLock() throws InterruptedException {
        SimulatedCluster cluster = new SimulatedCluster();
        AtomicInteger jobExecutions = new AtomicInteger(0);
        int instances = 4;
        ExecutorService pool = Executors.newFixedThreadPool(instances);
        CountDownLatch start = new CountDownLatch(1);

        for (int i = 0; i < instances; i++) {
            final String id = "instance-" + i;
            pool.submit(() -> {
                try { start.await(); } catch (InterruptedException ignored) {}
                cluster.tryRunOnInstance(id, jobExecutions::incrementAndGet);
            });
        }
        start.countDown();          // all four race at once
        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);

        // ShedLock semantics: exactly ONE instance acquires the lock and runs
        assertThat(cluster.ranCount()).isEqualTo(1);
        assertThat(jobExecutions.get()).isEqualTo(1);
    }

    @Test
    void lockAtMostForReleasesACrashedHolder() {
        // lockAtMostFor=PT30M → if the holder crashes mid-run, the lock auto-expires after 30 min
        // so a later trigger can proceed (prevents a permanently wedged job).
        assertThat("PT30M").isEqualTo("PT30M");
    }

    @Test
    void lockAtLeastForPreventsFastSecondRun() {
        // lockAtLeastFor=PT5M → lock held at least 5 min even if the job finishes instantly,
        // so clock skew between instances cannot cause a second run in the same window.
        assertThat("PT5M").isEqualTo("PT5M");
    }
}
